import { Plus, Search, SlidersHorizontal } from '@gntik-ai/icons';
import type { LucideIcon } from '@gntik-ai/icons';
import {
  Toggle,
  ToggleGroup,
  Toolbar,
  ToolbarButton,
  ToolbarEnd,
  ToolbarInput,
  ToolbarSeparator,
  ToolbarStart,
  cn,
  useI18n,
} from '@gntik-ai/ui';
import { useState, type ReactNode } from 'react';
import type { PageChromeAction } from '../types';
import { pageToolbarViews } from './fixtures';
import { useDebouncedText } from './use-debounced-text';

export interface PageToolbarView {
  value: string;
  /** Accessible name of the icon toggle. */
  label: string;
  icon: LucideIcon;
}

export interface PageToolbarProps {
  /** Controlled search text. */
  search?: string;
  defaultSearch?: string;
  onSearchChange?: (value: string) => void;
  /**
   * Milliseconds to wait after the last keystroke before calling `onSearchChange` (default 0: every keystroke).
   * The input still shows each keystroke at once; Enter and unmount report at once, and so does an emptied input.
   */
  searchDebounceMs?: number;
  searchLabel?: string;
  searchPlaceholder?: string;
  /**
   * Filter controls. Use ToolbarButton (optionally with `render` for a Menu/Popover trigger) so they
   * join the toolbar's arrow-key navigation. Omitted: a single "Filters" button; `null` hides it.
   */
  filters?: ReactNode;
  /** View modes for the segmented toggle; `null` or an empty list hides it. */
  views?: PageToolbarView[] | null;
  view?: string;
  defaultView?: string;
  onViewChange?: (value: string) => void;
  /** Main action at the end of the bar; `null` hides it. */
  primaryAction?: PageChromeAction | null;
  'aria-label'?: string;
  className?: string;
}

const pageToolbarDefaultAction: PageChromeAction = { label: 'New project', icon: Plus };

/** List/table toolbar: search, filters, view toggle and the primary action, with one Tab stop. */
export function PageToolbar({
  search,
  defaultSearch = '',
  onSearchChange,
  searchDebounceMs,
  searchLabel: searchLabelProp,
  searchPlaceholder = 'Search projects…',
  filters,
  views = pageToolbarViews,
  view,
  defaultView,
  onViewChange,
  primaryAction = pageToolbarDefaultAction,
  'aria-label': ariaLabelProp,
  className,
}: PageToolbarProps) {
  const { t } = useI18n();
  const searchLabel = searchLabelProp ?? t('common.search');
  const ariaLabel = ariaLabelProp ?? t('toolbar.label');
  const [innerSearch, setInnerSearch] = useState(defaultSearch);
  const [innerView, setInnerView] = useState(defaultView ?? views?.[0]?.value ?? '');
  const currentSearch = search ?? innerSearch;
  const searching = useDebouncedText(currentSearch, searchDebounceMs, (next) => {
    setInnerSearch(next);
    onSearchChange?.(next);
  });
  const currentView = view ?? innerView;

  return (
    <Toolbar aria-label={ariaLabel} className={cn('flex-wrap gap-y-2', className)}>
      <ToolbarStart className="min-w-0 flex-1 basis-60">
        <ToolbarInput
          type="search"
          icon={Search}
          aria-label={searchLabel}
          placeholder={searchPlaceholder}
          value={searching.text}
          onChange={(e) => searching.change(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter') searching.flush();
          }}
          wrapperClassName="max-w-sm"
        />
        {filters !== undefined ? (
          filters
        ) : (
          <ToolbarButton variant="secondary" icon={SlidersHorizontal}>
            Filters
          </ToolbarButton>
        )}
      </ToolbarStart>
      <ToolbarEnd>
        {views && views.length > 0 && (
          <>
            <ToggleGroup
              aria-label={t('toolbar.view')}
              size="sm"
              disallowEmptySelection
              value={[currentView]}
              onValueChange={(next) => {
                const picked = next[0] as string;
                setInnerView(picked);
                onViewChange?.(picked);
              }}
            >
              {views.map((v) => (
                <ToolbarButton
                  key={v.value}
                  render={<Toggle value={v.value} iconOnly size="sm" />}
                  aria-label={v.label}
                  icon={v.icon}
                  className="size-7 rounded-md data-pressed:bg-secondary data-pressed:text-foreground"
                />
              ))}
            </ToggleGroup>
            {primaryAction && <ToolbarSeparator />}
          </>
        )}
        {primaryAction && (
          <ToolbarButton
            variant={primaryAction.variant ?? 'primary'}
            icon={primaryAction.icon}
            disabled={primaryAction.disabled}
            onClick={primaryAction.onClick}
          >
            {primaryAction.label}
          </ToolbarButton>
        )}
      </ToolbarEnd>
    </Toolbar>
  );
}

import { LayoutGrid, List, Table2 } from '@gntik-ai/icons';
import type { PageToolbarView } from './PageToolbar';

export const pageToolbarViews: PageToolbarView[] = [
  { value: 'table', label: 'Table view', icon: Table2 },
  { value: 'list', label: 'List view', icon: List },
  { value: 'grid', label: 'Grid view', icon: LayoutGrid },
];

import { useEffect, useRef, useState } from 'react';

/**
 * Text that shows every keystroke at once but reports it once typing pauses for `delayMs`. With no delay
 * every change is reported at once. `flush` reports the pending text now, `replace` sets and reports a
 * text now and drops the pending one, and an unmount reports what is still pending. A `value` changed
 * from outside replaces the draft and the pending text.
 */
export function useDebouncedText(value: string, delayMs: number | undefined, onCommit: (text: string) => void) {
  const debounced = delayMs !== undefined && delayMs > 0;
  const [draft, setDraft] = useState(value);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const pending = useRef<string | null>(null);
  const reported = useRef(value);
  const latest = useRef(onCommit);
  useEffect(() => {
    latest.current = onCommit;
  });

  const commit = (text: string) => {
    clearTimeout(timer.current);
    timer.current = undefined;
    pending.current = null;
    reported.current = text;
    latest.current(text);
  };
  useEffect(() => {
    if (value === reported.current) return;
    reported.current = value;
    clearTimeout(timer.current);
    timer.current = undefined;
    pending.current = null;
    setDraft(value);
  }, [value]);
  useEffect(
    () => () => {
      clearTimeout(timer.current);
      if (pending.current !== null) latest.current(pending.current);
    },
    [],
  );

  return {
    text: debounced ? draft : value,
    change: (next: string) => {
      if (!debounced) return commit(next);
      setDraft(next);
      clearTimeout(timer.current);
      // An emptied input reports at once, like a clear.
      if (next === '') return commit(next);
      pending.current = next;
      timer.current = setTimeout(() => commit(next), delayMs);
    },
    flush: () => {
      if (pending.current !== null) commit(pending.current);
    },
    replace: (next: string) => {
      setDraft(next);
      commit(next);
    },
  };
}

import type { ButtonProps, MoreMenuAction } from '@gntik-ai/ui';
import type { LucideIcon } from '@gntik-ai/icons';

/** A header/toolbar action rendered as a kit Button (or a MoreMenu item when folded). */
export interface PageChromeAction {
  /** Stable key; defaults to `label`. */
  id?: string;
  label: string;
  icon?: LucideIcon;
  /** Button style; when omitted the block picks one (primary for the main action, secondary otherwise). */
  variant?: ButtonProps['variant'];
  disabled?: boolean;
  onClick?: () => void;
}

/** Maps a PageChromeAction to a MoreMenu item (destructive variant → destructive item). */
export function toMenuAction(action: PageChromeAction): MoreMenuAction {
  return {
    label: action.label,
    icon: action.icon,
    disabled: action.disabled,
    destructive: action.variant === 'destructive',
    onSelect: action.onClick,
  };
}
